          expect("LPAREN", "expected '(' after pin name");
          const netTok = parseName("expected net name");
          expect("RPAREN", "expected ')' after net name");
          if (pinTok && netTok) pins.push({ pin: pinTok.value, net: netTok.value, named: true });
